<?php require_once __DIR__.'/../includes/bootstrap.php'; require_role('admin');
$stats=$pdo->query("SELECT COUNT(*) total, SUM(status='aktif') aktif, SUM(status='nonaktif') nonaktif FROM kegiatan")->fetch();
$petugas=(int)$pdo->query('SELECT COUNT(*) FROM petugas WHERE deleted_at IS NULL')->fetchColumn();
$progress=(int)$pdo->query('SELECT COUNT(*) FROM progress_harian')->fetchColumn();
$rows=$pdo->query("SELECT k.*,u.username,(SELECT COUNT(*) FROM petugas p WHERE p.id_kegiatan=k.id_kegiatan AND p.deleted_at IS NULL) jumlah_petugas,(SELECT COUNT(*) FROM progress_harian ph WHERE ph.id_kegiatan=k.id_kegiatan) jumlah_progress FROM kegiatan k LEFT JOIN users u ON u.id_kegiatan=k.id_kegiatan ORDER BY k.created_at DESC")->fetchAll();
page_header('Dashboard Admin'); ?>
<div class="row g-3 mb-4"><div class="col-6 col-xl"><div class="card stat-card"><div class="muted-label">Total Kegiatan</div><div class="stat-value"><?=$stats['total']??0?></div></div></div><div class="col-6 col-xl"><div class="card stat-card"><div class="muted-label">Kegiatan Aktif</div><div class="stat-value"><?=$stats['aktif']??0?></div></div></div><div class="col-6 col-xl"><div class="card stat-card"><div class="muted-label">Kegiatan Nonaktif</div><div class="stat-value"><?=$stats['nonaktif']??0?></div></div></div><div class="col-6 col-xl"><div class="card stat-card"><div class="muted-label">Total Petugas</div><div class="stat-value"><?=$petugas?></div></div></div><div class="col-6 col-xl"><div class="card stat-card"><div class="muted-label">Total Progress</div><div class="stat-value"><?=$progress?></div></div></div></div>
<div class="card p-3 p-md-4"><div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-3"><div><h2 class="h5 fw-bold mb-1">Daftar Kegiatan</h2><div class="text-secondary small">Ringkasan seluruh kegiatan yang dikelola.</div></div><a class="btn btn-primary" href="<?=APP_BASE_URL?>/admin/kegiatan/create.php">+ Tambah Kegiatan</a></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>No</th><th>Nama Kegiatan</th><th>Periode</th><th>Akun Petugas</th><th>Petugas</th><th>Progress</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $i=>$r):?><tr><td><?=$i+1?></td><td><div class="fw-semibold"><?=e($r['nama_kegiatan'])?></div><div class="small text-secondary"><?=e($r['nomor_kegiatan'])?></div></td><td><?=format_tanggal($r['tanggal_mulai'])?> – <?=format_tanggal($r['tanggal_selesai'])?></td><td><?=e($r['username']??'-')?></td><td><?=$r['jumlah_petugas']?></td><td><?=$r['jumlah_progress']?></td><td><span class="badge text-bg-<?=$r['status']==='aktif'?'success':'secondary'?>"><?=e(ucfirst($r['status']))?></span></td><td><a class="btn btn-sm btn-outline-primary" href="<?=APP_BASE_URL?>/admin/kegiatan/detail.php?id=<?=$r['id_kegiatan']?>">Kelola</a></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="8" class="text-center text-secondary py-4">Belum ada kegiatan. Tambahkan kegiatan pertama.</td></tr><?php endif;?></tbody></table></div></div>
<?php page_footer(); ?>
